cd /private/tmp/note-dogfood-PdqO1q/pilot && node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");

// Check referenced IDs exist as elements
const ids = ["note", "clear"];
for (const id of ids) {
  const re = new RegExp(`id="${id}"`);
  if (!re.test(html)) { console.error(`MISSING element id="${id}"`); process.exit(1); }
  console.log(`OK element id="${id}" present`);
}

// Check the Clear handler empties the textarea
const script = html.match(/<script>([\s\S]*?)<\/script>/);
if (!script) { console.error("MISSING script block"); process.exit(1); }
const js = script[1];
if (!/note\.value\s*=\s*""/.test(js)) { console.error("Clear handler does not empty note"); process.exit(1); }
console.log("OK clear handler sets note.value = \"\"");

// Check no persistence (no localStorage/sessionStorage usage in stage 1)
if (/localStorage|sessionStorage/.test(js)) { console.error("Unexpected persistence in stage 1"); process.exit(1); }
console.log("OK no persistence APIs used");

// Check textarea is multiline
if (!/<textarea[^>]*>/.test(html)) { console.error("No textarea"); process.exit(1); }
console.log("OK multiline textarea present");

// Check button type=button so it does not submit/reload
if (!/<button[^>]*type="button"/.test(html)) { console.error("Button missing type=button"); process.exit(1); }
console.log("OK button is type=button");

// Check textarea starts empty (no default content)
const ta = html.match(/<textarea[^>]*>([\s\S]*?)<\/textarea>/);
if (ta && ta[1].trim().length > 0) { console.error("Textarea has default content"); process.exit(1); }
console.log("OK textarea starts empty");

console.log("ALL STATIC CHECKS PASSED");
'
